import os

from fastapi import applications
from fastapi.openapi.docs import get_swagger_ui_html
from fastapi.staticfiles import StaticFiles
from .. import __path__ as mngr_path


def cache_openapi_resources(api):
    """
    Use buffered swagger resources from /resources.

    :param api: FastAPI instance object
    """
    assets_path = f"{mngr_path[0]}{os.sep}resources"
    favicon_url = f"{assets_path}{os.sep}favicon.png"
    css_url = f"{assets_path}{os.sep}swagger-ui.css"
    js_url = f"{assets_path}{os.sep}swagger-ui-bundle.js"
    if os.path.exists(favicon_url) and os.path.exists(css_url) and os.path.exists(js_url):
        api.mount("/resources", StaticFiles(directory=assets_path), name="static")

        def patch_swagger_ui_html(*args, **kwargs):
            return get_swagger_ui_html(
                *args,
                **kwargs,
                swagger_favicon_url="/resources/favicon.png",
                swagger_css_url="/resources/swagger-ui.css",
                swagger_js_url="/resources/swagger-ui-bundle.js",
            )

        applications.get_swagger_ui_html = patch_swagger_ui_html
